int update_char_class_node(CClassNode* cc, OnigCodePoint* vs, enum CCVALTYPE* type, enum CCSTATE* state, ScanEnv* env) {
  int r = 0;
  OnigCodePoint c = *vs;

  switch (*state) {
    case CC_INIT:
      switch (*type) {
        case CCVAL_NOT:
          if (c < 0x100)
            BITSET_PUT(cc->bs, c);
          else
            range_add(&cc->ranges, c, c);
          *type = CCVAL_NORMAL;
          *state = CC_IN_RANGE;
          break;

        case CCVAL_NORMAL:
          if (c < 0x100)
            BITSET_PUT(cc->bs, c);
          else
            range_add(&cc->ranges, c, c);
          *state = CC_IN_RANGE;
          break;

        default:
          break;
      }
      break;

    case CC_IN_RANGE:
      if (c < 0x100)
        BITSET_PUT(cc->bs, c);
      else
        range_add(&cc->ranges, c, c);
      break;

    case CC_END:
      r = ONIGERR_INVALID_RANGE;
      break;
  }

  return r;
}

int update_ccnode(CClassNode* cc, OnigCodePoint* vs, enum CCVALTYPE* type, enum CCSTATE* state, ScanEnv* env) {
    int r = 0;

    switch (*state) {
        case CC_INIT:
            if (*type == CCVAL_INIT) {
                cc->type = *type;
                *state = CC_ADD;
            } else {
                r = ONIGERR_INVALID_PATTERN;
            }
            break;
        case CC_ADD:
            if (*type == CCVAL_BITSET) {
                BITSET_SET_VALUE(cc->mbit, *vs);
                *type = CCVAL_BITSET;
            } else if (*type == CCVAL_CODE_RANGES) {
                r = add_code_range(cc->code_range_head, vs, env);
                if (r != 0)
                    return r;
            } else {
                r = ONIGERR_INVALID_PATTERN;
            }
            break;
        case CC_END:
            r = ONIGERR_INVALID_PATTERN;
            break;
        default:
            r = ONIGERR_INVALID_PATTERN;
            break;
    }

    if (r == 0) {
        cc->type = *type;
        *state = (*state == CC_ADD) ? CC_INIT : *state;
    }

    return r;
}

int update_cclass_node(CClassNode* cc, OnigCodePoint* vs, enum CCVALTYPE* type, enum CCSTATE* state, ScanEnv* env) {
    int r = 0;

    switch (*state) {
        case CCINIT: {
            if (*type == CCVALSET) {
                BITSET_CLEAR(cc->bits);
            } else {
                cc->range.s = *vs;
                cc->range.e = *vs;
                *type = CCVALRANGE;
            }
            *state = CCINRANGE;
            break;
        }

        case CCINRANGE: {
            if (*type == CCVALSET) {
                BITSET_SET(cc->bits, *vs);
            } else {
                if (*vs > cc->range.e) {
                    cc->range.e = *vs;
                } else {
                    return ONIGERR_INVALID_PATTERN;
                }
            }
            break;
        }

        case CCEOF: {
            return ONIGERR_INVALID_PATTERN;
            break;
        }

        default:
            return ONIGERR_INVALID_PATTERN;
    }

    return r;
}

int update_char_class_node(CClassNode* cc, OnigCodePoint* vs, enum CCVALTYPE* type, enum CCSTATE* state, ScanEnv* env) {
    int r = 0;
    OnigCodePoint c = *vs;

    switch (*state) {
        case CCINIT: {
            switch (*type) {
                case CCBITSET:
                    r = onig_char_to_escaped_code(c, env);
                    if (r < 0) return r;
                    SET_CCLASS(c, cc);
                    break;
                case CCRAWCHR:
                    if (c < 0x100) {
                        r = onig_char_to_escaped_code(c, env);
                        if (r < 0) return r;
                        SET_CCLASS(c, cc);
                    } else {
                        ADD_CCLASS(c, cc);
                    }
                    break;
                case CCANYCHAR:
                    return ONIGERR_PARSER_FAILED;
                case CCCHR:
                    ADD_CCLASS(c, cc);
                    break;
                case CCRANGEREF:
                case CCNODATA:
                case CCVAL_MAX:
                    break;
            }
            *state = CCSET;
            break;
        }
        case CCSET: {
            switch (*type) {
                case CCBITSET:
                case CCRAWCHR:
                case CCCHR:
                    if (c < 0x100) {
                        r = onig_char_to_escaped_code(c, env);
                        if (r < 0) return r;
                        SET_CCLASS(c, cc);
                    } else {
                        ADD_CCLASS(c, cc);
                    }
                    break;
                case CCANYCHAR:
                    return ONIGERR_PARSER_FAILED;
                case CCRANGEREF:
                case CCNODATA:
                case CCVAL_MAX:
                    break;
            }
            *state = CCEND;
            break;
        }
        case CCEND:
            return ONIGERR_PARSER_FAILED;
    }
    return r;
}

int update_cclass_node(CClassNode* cc, OnigCodePoint* vs, enum CCVALTYPE* type, enum CCSTATE* state, ScanEnv* env) {
    switch (*state) {
        case CC_INIT:
            if (*type == CCVAL_ASCII) {
                BITSET_SET(cc->bs, *vs);
            } else {
                OnigRegion* range = onig_region_new();
                if (!range)
                    return ONIGERR_MEMORY;
                onig_region_set(range, 0, 0, *vs, *vs);
                if (cc->range_num >= ONIG_REGION_MAX_NUM) {
                    onig_region_free(range, 0);
                    return ONIGERR_MEMORY;
                }
                cc->range[cc->range_num++] = range;
            }
            *state = CC_ADD;
            break;

        case CC_ADD:
            if (*type == CCVAL_ASCII) {
                BITSET_SET(cc->bs, *vs);
            } else {
                if (cc->range_num >= ONIG_REGION_MAX_NUM)
                    return ONIGERR_MEMORY;
                OnigRegion* range = onig_region_new();
                if (!range)
                    return ONIGERR_MEMORY;
                onig_region_set(range, 0, 0, *vs, *vs);
                cc->range[cc->range_num++] = range;
            }
            break;

        case CC_END:
            return ONIGERR_END_OF_RANGE;

        default:
            return ONIGERR_INVALID_ARGUMENT;
    }

    return 0;
}
